-- Peony — mevcut site içeriğinin Supabase'e aktarımı
-- schema.sql çalıştırıldıktan SONRA bir kez çalıştırın.

on conflict (key) do update set value = excluded.value;

on conflict (slug) do update set position=excluded.position, image_url=excluded.image_url, name=excluded.name, description=excluded.description;





