  ('contact.phone', '{"th": "โทรศัพท์ &amp; อีเมล", "en": "Phone & email", "tr": "Telefon &amp; e-posta", "ru": "Телефон &amp; почта", "zh": "电话 &amp; 邮箱", "hi": "फ़ोन &amp; ईमेल"}'::jsonb),
  ('contact.text', '{"th": "ส่งคำขอด้านล่าง แล้วเราจะยืนยันการนัดหมายให้ในเวลาไม่นาน หรือโทรหาเราโดยตรงในเวลาทำการก็ได้", "en": "Send a request below and we will confirm your appointment shortly, or simply call us during opening hours.", "tr": "Aşağıdan talebinizi gönderin, randevunuzu kısa sürede teyit edelim; ya da açık olduğumuz saatlerde doğrudan arayın.", "ru": "Отправьте заявку ниже, и мы вскоре подтвердим запись; или просто позвоните нам в рабочие часы.", "zh": "在下方提交预约请求，我们会尽快为你确认；也可以在营业时间内直接致电。", "hi": "नीचे अनुरोध भेजिए, हम जल्दी ही आपका अपॉइंटमेंट पक्का कर देंगे; या खुलने के समय में सीधे फ़ोन कर लीजिए।"}'::jsonb),
  ('contact.title', '{"th": "แวะมาหาเราได้เลย", "en": "Come and find us", "tr": "Gelin, bizi bulun", "ru": "Приходите — мы рядом", "zh": "欢迎前来", "hi": "आइए, हमें ढूँढिए"}'::jsonb),
