  ('hero.eyebrow', '{"th": "นวดแผนไทย &amp; สปา", "en": "Thai Massage &amp; Spa", "tr": "Tayland Masajı &amp; Spa", "ru": "Тайский массаж &amp; спа", "zh": "泰式按摩 &amp; SPA", "hi": "थाई मसाज &amp; स्पा"}'::jsonb),
