  ('hero.text', '{"th": "ที่พักใจอันเงียบสงบ ที่ซึ่งศาสตร์การนวดแผนไทยดั้งเดิมมาบรรจบกับน้ำมันอุ่น ลูกประคบสมุนไพร และการดูแลอย่างไม่เร่งรีบ เพื่อให้กายและใจของคุณกลับมาสงบอีกครั้ง", "en": "A quiet retreat where traditional Thai technique meets warm oils, herbal compresses and unhurried attention — so your body and mind can settle again.", "tr": "Geleneksel Tayland tekniğinin sıcak yağlar, bitkisel kompresler ve acelesiz bir ilgiyle buluştuğu sessiz bir sığınak — bedeniniz ve zihniniz yeniden yerine otursun diye.", "ru": "Тихое убежище, где традиционная тайская техника соединяется с тёплыми маслами, травяными компрессами и неторопливым вниманием — чтобы тело и мысли снова пришли в равновесие.", "zh": "一处安静的栖息地，传统泰式手法在这里遇见温热精油、草药热敷包与不被催促的专注照护——让身体与心绪重新安顿下来。", "hi": "एक शांत ठिकाना, जहाँ पारंपरिक थाई तकनीक गर्म तेलों, हर्बल कंप्रेस और बिना जल्दबाज़ी वाले ध्यान से मिलती है — ताकि आपका शरीर और मन फिर से ठहर सकें।"}'::jsonb),
  ('hero.title', '{"th": "นวดแผนไทยดั้งเดิม ที่ Peony", "en": "Traditional Thai Massage at Peony", "tr": "Peony ile Geleneksel Tayland Masajı", "ru": "Традиционный тайский массаж в Peony", "zh": "在 Peony 体验传统泰式按摩", "hi": "Peony में पारंपरिक थाई मसाज"}'::jsonb),
  ('meta.description', '{"th": "นวดแผนไทยดั้งเดิม พิธีกรรมน้ำมันหอมระเหย และการดูแลอย่างสงบ ไม่เร่งรีบ", "en": "Traditional Thai therapies, aromatic oil rituals and quiet, unhurried care.", "tr": "Geleneksel Tayland terapileri, aromatik yağ ritüelleri ve sessiz, aceleye getirilmeyen bir bakım.", "ru": "Традиционные тайские техники, ритуалы с ароматическими маслами и спокойный, неторопливый уход.", "zh": "传统泰式手法、芳香精油仪式，以及安静从容、不被催促的照护。", "hi": "पारंपरिक थाई तकनीक, सुगंधित तेल के अनुष्ठान और शांत, बिना जल्दबाज़ी वाली देखभाल।"}'::jsonb),
  ('meta.title', '{"th": "Peony Thai Massage & Spa", "en": "Peony Thai Massage & Spa", "tr": "Peony Thai Massage & Spa", "ru": "Peony Thai Massage & Spa", "zh": "Peony Thai Massage & Spa", "hi": "Peony Thai Massage & Spa"}'::jsonb),
  ('nav.about', '{"th": "เกี่ยวกับเรา", "en": "About", "tr": "Hakkımızda", "ru": "О нас", "zh": "关于我们", "hi": "हमारे बारे में"}'::jsonb),
  ('nav.book', '{"th": "จองคิว", "en": "Book Appointment", "tr": "Randevu Al", "ru": "Записаться", "zh": "预约", "hi": "अपॉइंटमेंट लें"}'::jsonb),
  ('nav.contact', '{"th": "ติดต่อเรา", "en": "Contact", "tr": "İletişim", "ru": "Контакты", "zh": "联系我们", "hi": "संपर्क"}'::jsonb),
  ('nav.faq', '{"th": "คำถามที่พบบ่อย", "en": "FAQ", "tr": "S.S.S.", "ru": "Вопросы", "zh": "常见问题", "hi": "सामान्य प्रश्न"}'::jsonb),
  ('nav.gallery', '{"th": "แกลเลอรี", "en": "Gallery", "tr": "Galeri", "ru": "Галерея", "zh": "环境相册", "hi": "गैलरी"}'::jsonb),
  ('nav.plans', '{"th": "แพ็กเกจ", "en": "Packages", "tr": "Paketler", "ru": "Пакеты", "zh": "套餐", "hi": "पैकेज"}'::jsonb),
  ('nav.services', '{"th": "บริการนวด", "en": "Treatments", "tr": "Uygulamalar", "ru": "Процедуры", "zh": "理疗项目", "hi": "उपचार"}'::jsonb),
  ('plans.badge', '{"th": "ได้รับความนิยมที่สุด", "en": "Most chosen", "tr": "En çok tercih edilen", "ru": "Выбирают чаще всего", "zh": "最多人选择", "hi": "सबसे ज़्यादा चुना गया"}'::jsonb),
  ('plans.cta', '{"th": "เลือกแพ็กเกจนี้", "en": "Book this", "tr": "Bunu seç", "ru": "Выбрать", "zh": "选择此套餐", "hi": "यह चुनें"}'::jsonb),
  ('plans.eyebrow', '{"th": "แพ็กเกจ", "en": "Packages", "tr": "Paketler", "ru": "Пакеты", "zh": "套餐", "hi": "पैकेज"}'::jsonb),
  ('plans.text', '{"th": "สามวิธีในการใช้เวลากับเรา ไม่มีการขายเพิ่มที่เคาน์เตอร์ ไม่มีอะไรเซอร์ไพรส์", "en": "Three ways to spend your time with us. No add-ons at the counter, no surprises.", "tr": "Bizimle vakit geçirmenin üç yolu. Kasada ek satış yok, sürpriz yok.", "ru": "Три способа провести время у нас. Никаких допродаж на ресепшене и никаких сюрпризов.", "zh": "三种与我们共度时光的方式。前台不做额外推销，也没有意外收费。", "hi": "हमारे साथ समय बिताने के तीन तरीक़े। काउंटर पर कोई अतिरिक्त बिक्री नहीं, कोई हैरानी नहीं।"}'::jsonb),
  ('plans.title', '{"th": "ราคาเรียบง่าย ตรงไปตรงมา", "en": "Simple, honest pricing", "tr": "Sade ve dürüst fiyatlandırma", "ru": "Простые и честные цены", "zh": "价格简单、透明", "hi": "सरल और साफ़ कीमतें"}'::jsonb),
  ('quotes.eyebrow', '{"th": "เสียงจากลูกค้า", "en": "Guest Notes", "tr": "Misafir Notları", "ru": "Отзывы гостей", "zh": "客人留言", "hi": "मेहमानों के शब्द"}'::jsonb),
  ('quotes.title', '{"th": "สิ่งที่ลูกค้าพูดหลังออกจากห้อง", "en": "What people say afterwards", "tr": "Sonrasında söyledikleri", "ru": "Что говорят после сеанса", "zh": "结束之后，他们这样说", "hi": "बाद में लोग क्या कहते हैं"}'::jsonb),
  ('services.eyebrow', '{"th": "บริการนวด", "en": "Treatments", "tr": "Uygulamalar", "ru": "Процедуры", "zh": "理疗项目", "hi": "उपचार"}'::jsonb),
  ('services.text', '{"th": "ทุกบริการเริ่มต้นด้วยการพูดคุยสั้น ๆ เพื่อให้แรงกด น้ำมัน และจังหวะ เหมาะกับตัวคุณ ไม่ใช่เหมาะกับรายการในเมนู", "en": "Every treatment begins with a short conversation, so the pressure, oils and pace are matched to you rather than to a menu.", "tr": "Her uygulama kısa bir sohbetle başlar; böylece basınç, yağ ve tempo bir menüye değil size göre ayarlanır.", "ru": "Каждая процедура начинается с короткого разговора — чтобы давление, масла и темп подбирались под вас, а не под пункт меню.", "zh": "每次理疗都从简短沟通开始，让力度、精油与节奏贴合你本人，而不是贴合菜单上的某一行。", "hi": "हर उपचार एक छोटी बातचीत से शुरू होता है, ताकि दबाव, तेल और गति किसी मेन्यू के नहीं, आपके अनुसार तय हों।"}'::jsonb),
  ('services.title', '{"th": "เลือกตามความรู้สึกของคุณในวันนี้", "en": "Chosen for how you feel today", "tr": "Bugün nasıl hissettiğinize göre seçilir", "ru": "Выбирается по вашему сегодняшнему состоянию", "zh": "按你今天的状态来挑选", "hi": "आज आप कैसा महसूस कर रहे हैं, उसी के अनुसार"}'::jsonb)
insert into peony_services (slug, position, image_url, name, description) values
  ('thai', 0, 'assets/art/svc-thai.svg', '{"th": "นวดแผนไทยดั้งเดิม", "en": "Traditional Thai Massage", "tr": "Geleneksel Tayland Masajı", "ru": "Традиционный тайский массаж", "zh": "传统泰式按摩", "hi": "पारंपरिक थाई मसाज"}'::jsonb, '{"th": "นวดแบบไม่ใช้น้ำมันบนเบาะ พร้อมการยืดเหยียดและแรงกดเป็นจังหวะตามแนวเส้นพลังงานของร่างกาย", "en": "Dry massage on a mat with guided stretching and rhythmic pressure along the body''s energy lines.", "tr": "Minder üzerinde, eşlikli esnetmeler ve vücudun enerji hatları boyunca ritmik basınçla uygulanan kuru masaj.", "ru": "Сухой массаж на мате с мягкими растяжками и ритмичным давлением вдоль энергетических линий тела.", "zh": "在垫上进行的无油按摩，配合引导式伸展，沿身体能量线施以有节奏的按压。", "hi": "गद्दे पर बिना तेल की मसाज, जिसमें शरीर की ऊर्जा रेखाओं पर लयबद्ध दबाव और सहायक स्ट्रेचिंग होती है।"}'::jsonb),
  ('oil', 1, 'assets/art/svc-oil.svg', '{"th": "นวดน้ำมันสไตล์ไทย", "en": "Thai Oil Massage", "tr": "Tayland Yağ Masajı", "ru": "Тайский массаж с маслом", "zh": "泰式精油按摩", "hi": "थाई ऑइल मसाज"}'::jsonb, '{"th": "การลูบไล้ยาวต่อเนื่องด้วยน้ำมันอุ่น ช่วยคลายกล้ามเนื้อที่ตึงและทำให้จิตใจที่ว้าวุ่นสงบลง", "en": "Long, flowing strokes with warm oil to soften tight muscle and quiet a restless mind.", "tr": "Sıcak yağla uzun, akıcı hareketler; gergin kası yumuşatır, huzursuz zihni susturur.", "ru": "Длинные плавные движения с тёплым маслом: расслабляют зажатые мышцы и успокаивают беспокойные мысли.", "zh": "以温热精油进行绵长流畅的推抚，舒缓紧绷的肌肉，也让浮躁的思绪静下来。", "hi": "गर्म तेल के साथ लंबे, बहते स्ट्रोक — कसी हुई मांसपेशियों को ढीला करते हैं और बेचैन मन को शांत।"}'::jsonb),
  ('aroma', 2, 'assets/art/svc-aroma.svg', '{"th": "นวดอโรมาเธอราพี", "en": "Aromatherapy Massage", "tr": "Aroma Terapi Masajı", "ru": "Ароматерапевтический массаж", "zh": "芳香疗法按摩", "hi": "अरोमाथेरेपी मसाज"}'::jsonb, '{"th": "การนวดอย่างนุ่มนวลด้วยน้ำมันหอมระเหยที่เลือกให้เหมาะกับคุณ — ผ่อนคลาย กระปรี้กระเปร่า หรือปรับสมดุล", "en": "Gentle bodywork with an essential-oil blend chosen for you — calming, reviving or balancing.", "tr": "Size özel seçilen uçucu yağ karışımıyla nazik bir çalışma — sakinleştirici, canlandırıcı ya da dengeleyici.", "ru": "Мягкая работа с телом и смесью эфирных масел, подобранной для вас — успокаивающей, бодрящей или балансирующей.", "zh": "以为你调配的精油进行轻柔的身体照护——安神、提振或平衡，由你的状态决定。", "hi": "आपके लिए चुने गए एसेंशियल ऑइल मिश्रण के साथ कोमल बॉडीवर्क — शांत करने वाला, स्फूर्ति देने वाला या संतुलन बनाने वाला।"}'::jsonb),
  ('foot', 3, 'assets/art/svc-foot.svg', '{"th": "นวดกดจุดฝ่าเท้า", "en": "Foot Reflexology", "tr": "Ayak Refleksolojisi", "ru": "Рефлексология стоп", "zh": "足部反射疗法", "hi": "फुट रिफ्लेक्सोलॉजी"}'::jsonb, '{"th": "แรงกดเฉพาะจุดสะท้อนบริเวณฝ่าเท้าและน่อง ให้ความรู้สึกมั่นคงและผ่อนคลายอย่างลึกซึ้ง", "en": "Focused pressure on the reflex points of the feet and lower legs. Deeply grounding.", "tr": "Ayak ve alt bacaktaki refleks noktalarına odaklı basınç. Derinden yere basma hissi verir.", "ru": "Точечное давление на рефлекторные зоны стоп и голеней. Глубоко заземляет и снимает усталость.", "zh": "针对足底与小腿反射区的定点按压，让人由内而外地踏实放松。", "hi": "पैरों और पिंडलियों के रिफ्लेक्स बिंदुओं पर केंद्रित दबाव। गहराई तक स्थिर और हल्का महसूस कराता है।"}'::jsonb),
  ('back', 4, 'assets/art/svc-back.svg', '{"th": "นวดหลัง คอ &amp; บ่า", "en": "Back, Neck & Shoulders", "tr": "Sırt, Boyun &amp; Omuz", "ru": "Спина, шея &amp; плечи", "zh": "背颈肩理疗", "hi": "पीठ, गर्दन &amp; कंधे"}'::jsonb, '{"th": "คอร์สสั้นที่เจาะจงความตึงซึ่งสะสมจากการนั่งโต๊ะ จ้องหน้าจอ และการเดินทางไกล", "en": "A short, targeted session for the tension that builds from desks, screens and long drives.", "tr": "Masa başı, ekran ve uzun yol yüzünden biriken gerginlik için kısa ve hedefli bir seans.", "ru": "Короткий целевой сеанс для напряжения, которое копится от работы за столом, экранов и долгой дороги.", "zh": "针对久坐办公、长时间看屏幕与长途驾驶所累积的紧绷，进行短时精准的处理。", "hi": "डेस्क, स्क्रीन और लंबी ड्राइव से जमा हुए तनाव के लिए छोटा, लक्षित सत्र।"}'::jsonb),
  ('herbal', 5, 'assets/art/svc-herbal.svg', '{"th": "ประคบสมุนไพร", "en": "Herbal Compress", "tr": "Bitkisel Kompres", "ru": "Травяной компресс", "zh": "泰式草药热敷", "hi": "हर्बल कंप्रेस"}'::jsonb, '{"th": "ลูกประคบสมุนไพรไทยนึ่งร้อน กดลงบนกล้ามเนื้อ — อบอุ่น หอม และช้า ๆ", "en": "Steamed pouches of Thai herbs pressed into the muscle — warm, aromatic and slow.", "tr": "Buharda ısıtılmış Tayland bitki keseleri kasa bastırılır — sıcak, aromatik ve yavaş.", "ru": "Распаренные мешочки с тайскими травами прижимаются к мышцам — тепло, ароматно и медленно.", "zh": "蒸热的泰式草药包按压于肌肉之上——温热、芳香，节奏缓慢。", "hi": "भाप में गरम की गई थाई जड़ी-बूटियों की पोटलियाँ मांसपेशियों पर दबाई जाती हैं — गर्म, सुगंधित और धीमी।"}'::jsonb),
  ('scrub', 6, 'assets/art/svc-scrub.svg', '{"th": "ขัดผิวและบำรุงผิวกาย", "en": "Body Scrub & Polish", "tr": "Vücut Peelingi", "ru": "Скраб и полировка тела", "zh": "全身去角质护理", "hi": "बॉडी स्क्रब &amp; पॉलिश"}'::jsonb, '{"th": "สครับจากแร่ธาตุและสมุนไพร ช่วยผลัดผิวหมองคล้ำ ให้ผิวเรียบเนียนและนุ่มชุ่มชื้น", "en": "A mineral and botanical scrub that lifts dull skin and leaves it smooth and soft.", "tr": "Mineral ve bitkisel peeling; matlaşmış cildi arındırır, pürüzsüz ve yumuşak bırakır.", "ru": "Минерально-растительный скраб снимает тусклый слой кожи и оставляет её гладкой и мягкой.", "zh": "矿物与植萃磨砂，温和带走暗沉角质，留下平滑柔软的肤感。", "hi": "खनिज और वनस्पति स्क्रब, जो निस्तेज त्वचा हटाकर उसे चिकना और मुलायम छोड़ता है।"}'::jsonb),
  ('facial', 7, 'assets/art/svc-facial.svg', '{"th": "ทรีตเมนต์บำรุงผิวหน้า", "en": "Facial Ritual", "tr": "Yüz Bakım Ritüeli", "ru": "Ритуал для лица", "zh": "面部护理仪式", "hi": "फेशियल रिचुअल"}'::jsonb, '{"th": "ทำความสะอาด นวดหน้าอย่างนุ่มนวล และมาสก์บำรุง ปิดท้ายด้วยผ้าประคบสมุนไพรเย็น", "en": "Cleansing, gentle massage and a nourishing mask, finished with a cool herbal compress.", "tr": "Temizlik, nazik masaj ve besleyici bir maske; serin bitkisel kompresle tamamlanır.", "ru": "Очищение, мягкий массаж и питательная маска, в завершение — прохладный травяной компресс.", "zh": "清洁、轻柔按摩与滋养面膜，最后以清凉草药敷布收尾。", "hi": "सफ़ाई, कोमल मसाज और पोषक मास्क, अंत में ठंडे हर्बल कंप्रेस के साथ।"}'::jsonb)
insert into peony_plans (position, featured, name, note, items) values
  (0, false, '{"th": "Essential", "en": "Essential", "tr": "Temel", "ru": "Essential", "zh": "Essential", "hi": "Essential"}'::jsonb, '{"th": "การรีเซ็ตสั้น ๆ สำหรับวันที่เวลามีน้อย แต่ความตึงเครียดมีมาก", "en": "A short reset when time is tight but tension is not.", "tr": "Zamanın kısıtlı, gerginliğin bol olduğu günler için kısa bir sıfırlama.", "ru": "Короткая перезагрузка, когда времени мало, а напряжения — много.", "zh": "时间紧、压力却不小的日子里，一次简短的重启。", "hi": "उन दिनों के लिए छोटा रीसेट, जब समय कम हो पर तनाव कम न हो।"}'::jsonb, '{"th": ["เน้นหลัง คอ และบ่า", "ปิดท้ายด้วยผ้าขนหนูอุ่น", "ชาสมุนไพรหลังนวด", "นักบำบัดหนึ่งท่าน"], "en": ["Back, neck & shoulder focus", "Warm towel finish", "Herbal tea afterwards", "Single therapist"], "tr": ["Sırt, boyun ve omuz odaklı", "Sıcak havlu bitişi", "Sonrasında bitki çayı", "Tek terapist"], "ru": ["Акцент на спине, шее и плечах", "Завершение тёплым полотенцем", "Травяной чай после сеанса", "Один мастер"], "zh": ["聚焦背、颈与肩", "温热毛巾收尾", "理疗后草本茶", "单人理疗师"], "hi": ["पीठ, गर्दन और कंधों पर ध्यान", "गर्म तौलिए के साथ समापन", "बाद में हर्बल चाय", "एक थेरेपिस्ट"]}'::jsonb),
  (1, true, '{"th": "Signature", "en": "Signature", "tr": "İmza", "ru": "Signature", "zh": "Signature", "hi": "Signature"}'::jsonb, '{"th": "ทรีตเมนต์เต็มตัวประจำร้าน — คอร์สที่ลูกค้ากลับมาใช้บริการซ้ำมากที่สุด", "en": "Our full-body ritual — the one most guests come back for.", "tr": "Tüm vücut ritüelimiz — misafirlerin en çok geri döndüğü seçenek.", "ru": "Наш ритуал для всего тела — именно за ним гости возвращаются чаще всего.", "zh": "我们的全身理疗仪式——回头客最常选择的一项。", "hi": "हमारा पूरे शरीर का अनुष्ठान — जिसके लिए मेहमान सबसे ज़्यादा लौटते हैं।"}'::jsonb, '{"th": ["นวดแผนไทยหรือนวดน้ำมันเต็มตัว", "เลือกน้ำมันอโรมาได้เอง", "ปิดท้ายด้วยนวดกดจุดฝ่าเท้า", "เพิ่มลูกประคบสมุนไพรได้ตามต้องการ", "ชาสมุนไพรหลังนวด"], "en": ["Full body Thai or oil massage", "Aromatherapy oil of your choice", "Foot reflexology finish", "Herbal compress on request", "Herbal tea afterwards"], "tr": ["Tüm vücut Tayland ya da yağ masajı", "Seçtiğiniz aroma terapi yağı", "Ayak refleksolojisi bitişi", "İstenirse bitkisel kompres", "Sonrasında bitki çayı"], "ru": ["Тайский или масляный массаж всего тела", "Аромамасло на ваш выбор", "Завершение рефлексологией стоп", "Травяной компресс по желанию", "Травяной чай после сеанса"], "zh": ["全身泰式或精油按摩", "自选芳疗精油", "足部反射疗法收尾", "可按需加草药热敷", "理疗后草本茶"], "hi": ["पूरे शरीर की थाई या ऑइल मसाज", "अपनी पसंद का अरोमा ऑइल", "फुट रिफ्लेक्सोलॉजी के साथ समापन", "अनुरोध पर हर्बल कंप्रेस", "बाद में हर्बल चाय"]}'::jsonb),
  (2, false, '{"th": "Retreat", "en": "Retreat", "tr": "İnziva", "ru": "Retreat", "zh": "Retreat", "hi": "Retreat"}'::jsonb, '{"th": "ครึ่งวันอันไม่เร่งรีบ สำหรับวันที่คุณอยากหายไปจากทุกสิ่งสักพัก", "en": "An unhurried half-day for when you want to disappear for a while.", "tr": "Bir süreliğine kaybolmak istediğiniz, acelesiz bir yarım gün.", "ru": "Неторопливые полдня для тех, кто хочет ненадолго исчезнуть.", "zh": "想暂时从一切中消失时，一个不赶时间的半天。", "hi": "एक बिना जल्दबाज़ी वाला आधा दिन, जब आप कुछ देर के लिए ग़ायब हो जाना चाहें।"}'::jsonb, '{"th": ["นวดเต็มตัว", "ขัดผิวและบำรุงผิวกาย", "ทรีตเมนต์บำรุงผิวหน้า", "นวดกดจุดฝ่าเท้า", "ห้องส่วนตัว", "รวมเครื่องดื่มและของว่าง"], "en": ["Full body massage", "Body scrub & polish", "Facial ritual", "Foot reflexology", "Private room", "Refreshments included"], "tr": ["Tüm vücut masajı", "Vücut peelingi", "Yüz bakım ritüeli", "Ayak refleksolojisi", "Özel oda", "İkramlar dâhil"], "ru": ["Массаж всего тела", "Скраб и полировка тела", "Ритуал для лица", "Рефлексология стоп", "Отдельный кабинет", "Напитки и угощение включены"], "zh": ["全身按摩", "全身去角质护理", "面部护理仪式", "足部反射疗法", "独立房间", "含茶点招待"], "hi": ["पूरे शरीर की मसाज", "बॉडी स्क्रब और पॉलिश", "फेशियल रिचुअल", "फुट रिफ्लेक्सोलॉजी", "निजी कमरा", "जलपान शामिल"]}'::jsonb);
insert into peony_faqs (position, question, answer) values
  (0, '{"th": "ต้องจองล่วงหน้าหรือไม่?", "en": "Do I need to book in advance?", "tr": "Önceden randevu almam gerekiyor mu?", "ru": "Нужно ли записываться заранее?", "zh": "需要提前预约吗？", "hi": "क्या पहले से बुकिंग ज़रूरी है?"}'::jsonb, '{"th": "เราแนะนำให้จองล่วงหน้า โดยเฉพาะช่วงเย็นและวันหยุดสุดสัปดาห์ ลูกค้า walk-in ยินดีต้อนรับเสมอเมื่อมีนักบำบัดว่าง แต่การจองจะช่วยยืนยันห้องและเวลาที่คุณต้องการ", "en": "We recommend it, especially in the evenings and at weekends. Walk-ins are welcome whenever a therapist is free, but booking guarantees the room and the time you want.", "tr": "Özellikle akşam saatleri ve hafta sonları için öneririz. Terapist müsait olduğunda randevusuz da kabul ediyoruz, ancak randevu istediğiniz odayı ve saati garantiler.", "ru": "Рекомендуем, особенно на вечерние часы и выходные. Без записи мы тоже принимаем, когда мастер свободен, но запись гарантирует нужный вам кабинет и время.", "zh": "建议提前预约，尤其是傍晚时段与周末。理疗师有空档时也欢迎直接到店，但预约能确保你想要的房间与时间。", "hi": "हम सलाह देते हैं, ख़ासकर शाम और सप्ताहांत के लिए। थेरेपिस्ट खाली होने पर बिना बुकिंग भी स्वागत है, पर बुकिंग से आपका मनचाहा कमरा और समय तय हो जाता है।"}'::jsonb),
  (1, '{"th": "ควรแต่งกายอย่างไร?", "en": "What should I wear?", "tr": "Ne giymeliyim?", "ru": "Что надеть?", "zh": "该穿什么？", "hi": "क्या पहनकर आएँ?"}'::jsonb, '{"th": "สำหรับนวดแผนไทยดั้งเดิม เรามีชุดผ้าฝ้ายหลวมสบายให้เปลี่ยน ส่วนทรีตเมนต์น้ำมัน คุณถอดเสื้อผ้าได้เท่าที่รู้สึกสบายใจ และจะมีผ้าคลุมให้ตลอดการนวด", "en": "For traditional Thai massage we provide loose cotton clothing you change into. For oil treatments you undress to your comfort level and are covered with towels throughout.", "tr": "Geleneksel Tayland masajı için üzerinizi değiştireceğiniz bol pamuklu kıyafet veriyoruz. Yağlı uygulamalarda rahat ettiğiniz kadar soyunursunuz ve seans boyunca havluyla örtülü kalırsınız.", "ru": "Для традиционного тайского массажа мы выдаём свободную хлопковую одежду для переодевания. Для процедур с маслом вы раздеваетесь настолько, насколько вам комфортно, и всё время остаётесь укрыты полотенцами.", "zh": "传统泰式按摩我们会提供宽松棉质服装供你更换。精油类项目则可依自己觉得舒适的程度着装，全程都会以浴巾覆盖。", "hi": "पारंपरिक थाई मसाज के लिए हम ढीले सूती कपड़े देते हैं, जिन्हें आप बदल लेते हैं। तेल वाले उपचारों में आप अपनी सहजता के अनुसार कपड़े उतारते हैं और पूरे समय तौलिए से ढके रहते हैं।"}'::jsonb),
  (2, '{"th": "ควรมาถึงก่อนเวลานานแค่ไหน?", "en": "How early should I arrive?", "tr": "Ne kadar erken gelmeliyim?", "ru": "За сколько приходить?", "zh": "应该提前多久到？", "hi": "कितनी जल्दी पहुँचना चाहिए?"}'::jsonb, '{"th": "มาก่อนเวลานัดสักสิบนาทีก็เพียงพอ จะได้มีเวลาเปลี่ยนชุด จิบชาสักถ้วย และบอกนักบำบัดว่าวันนี้ร่างกายคุณต้องการอะไร", "en": "Ten minutes before your appointment is plenty. It gives you time to change, have a cup of tea, and tell your therapist what your body needs today.", "tr": "Randevunuzdan on dakika önce yeterli. Üzerinizi değiştirmeye, bir fincan çay içmeye ve terapistinize bugün bedeninizin neye ihtiyacı olduğunu anlatmaya vakit kalır.", "ru": "Десяти минут до начала вполне достаточно. Успеете переодеться, выпить чашку чая и рассказать мастеру, что вашему телу нужно сегодня.", "zh": "提前十分钟就足够了。足以更衣、喝杯茶，并告诉理疗师你的身体今天需要什么。", "hi": "अपॉइंटमेंट से दस मिनट पहले पर्याप्त है। इतने में आप कपड़े बदल सकते हैं, एक कप चाय पी सकते हैं और थेरेपिस्ट को बता सकते हैं कि आज आपके शरीर को क्या चाहिए।"}'::jsonb),
  (3, '{"th": "เหมาะกับผู้ที่มาครั้งแรกหรือไม่?", "en": "Is it suitable for a first-time guest?", "tr": "İlk kez gelen biri için uygun mu?", "ru": "Подойдёт ли новичку?", "zh": "第一次来合适吗？", "hi": "क्या यह पहली बार आने वालों के लिए ठीक है?"}'::jsonb, '{"th": "เหมาะอย่างยิ่ง เพียงบอกเราว่าเป็นครั้งแรก นักบำบัดจะเริ่มอย่างนุ่มนวล อธิบายทุกขั้นตอน และปรับน้ำหนักมือไปตลอด ไม่ควรมีจังหวะไหนที่ทำให้เจ็บ", "en": "Very much so. Tell us it is your first visit and your therapist will start gently, explain each stage and adjust the pressure as you go. Nothing should ever hurt.", "tr": "Fazlasıyla. İlk ziyaretiniz olduğunu söyleyin; terapistiniz nazik başlar, her aşamayı anlatır ve ilerledikçe basıncı ayarlar. Hiçbir aşamada canınız yanmamalı.", "ru": "Вполне. Скажите, что вы у нас впервые — мастер начнёт мягко, объяснит каждый этап и будет корректировать давление по ходу. Больно быть не должно ни на одном этапе.", "zh": "非常合适。告诉我们是初次到访，理疗师会从轻缓开始，逐步说明每个阶段，并随时调整力度。任何环节都不该让你感到疼痛。", "hi": "बिल्कुल। बता दीजिए कि यह आपकी पहली बार है — थेरेपिस्ट धीरे शुरू करेंगे, हर चरण समझाएँगे और साथ-साथ दबाव समायोजित करेंगे। कहीं भी दर्द नहीं होना चाहिए।"}'::jsonb),
  (4, '{"th": "เลือกน้ำหนักมือเองได้ไหม?", "en": "Can I choose the pressure?", "tr": "Basıncı ben seçebilir miyim?", "ru": "Можно ли выбрать силу нажима?", "zh": "力度可以自己选吗？", "hi": "क्या मैं दबाव चुन सकता/सकती हूँ?"}'::jsonb, '{"th": "ได้เสมอ เบา กลาง หรือหนัก และเปลี่ยนใจกลางคันก็ได้ เพียงบอกเรา นักบำบัดยินดีปรับให้มากกว่าปล่อยให้คุณฝืนทน", "en": "Always. Light, medium or firm — and you can change your mind halfway through. Just say the word; your therapist would far rather adjust than have you endure.", "tr": "Her zaman. Hafif, orta ya da sert — üstelik seansın ortasında fikrinizi değiştirebilirsiniz. Söylemeniz yeterli; terapistiniz sizin katlanmanızdansa ayar yapmayı çok daha çok ister.", "ru": "Всегда. Лёгкий, средний или сильный — и передумать можно прямо посреди сеанса. Просто скажите: мастеру гораздо важнее подстроиться, чем видеть, как вы терпите.", "zh": "随时可以。轻、中或重都行，中途改主意也没问题。开口说一声即可——比起让你忍着，理疗师更希望及时调整。", "hi": "हमेशा। हल्का, मध्यम या तेज़ — और बीच में मन भी बदल सकते हैं। बस कह दीजिए; थेरेपिस्ट आपको सहते देखने के बजाय समायोजन करना कहीं ज़्यादा पसंद करेंगे।"}'::jsonb),
  (5, '{"th": "นโยบายการยกเลิกเป็นอย่างไร?", "en": "What is your cancellation policy?", "tr": "İptal koşullarınız nedir?", "ru": "Каковы условия отмены?", "zh": "取消政策是怎样的？", "hi": "रद्द करने की नीति क्या है?"}'::jsonb, '{"th": "แจ้งล่วงหน้าอย่างน้อยสองสามชั่วโมง ไม่มีค่าใช้จ่ายใด ๆ เรื่องไม่คาดคิดเกิดขึ้นได้เสมอ เราเพียงอยากเปิดคิวให้ลูกค้าท่านอื่นมากกว่าปล่อยห้องว่างไว้เฉย ๆ", "en": "Let us know at least a few hours ahead and there is no charge at all. Life happens; we would simply rather offer the slot to someone else than leave the room empty.", "tr": "En az birkaç saat önceden haber verin, hiçbir ücret alınmaz. Hayat işte; odayı boş bırakmaktansa saati başka birine açmayı tercih ederiz.", "ru": "Предупредите хотя бы за несколько часов — никакой платы не будет. Всякое случается; нам просто важнее отдать это время другому гостю, чем оставить кабинет пустым.", "zh": "至少提前几小时告知，我们不收取任何费用。生活总有变化；与其让房间空着，我们更愿意把这个时段留给其他客人。", "hi": "कम से कम कुछ घंटे पहले बता दीजिए, कोई शुल्क नहीं लगेगा। ज़िंदगी में सब कुछ होता है; हम कमरा खाली रखने के बजाय वह समय किसी और को देना पसंद करेंगे।"}'::jsonb);
insert into peony_testimonials (position, author, role, body) values
  (0, '-doldurulacak-', '-doldurulacak-', '{"th": "ฉันเดินเข้ามาพร้อมงานที่ค้างมาทั้งสัปดาห์ และเดินออกไปโดยไม่มีมันติดตัว นักบำบัดอ่านความตึงที่บ่าของฉันออกก่อนที่ฉันจะเอ่ยปากเสียอีก", "en": "I walked in carrying a week of deadlines and walked out without them. The therapist read the tension in my shoulders before I said a word.", "tr": "İçeri bir haftalık teslim tarihiyle girdim, onlarsız çıktım. Terapist ben tek kelime etmeden omzumdaki gerginliği okudu.", "ru": "Я пришла с грузом недельных дедлайнов, а вышла уже без него. Мастер прочитал напряжение в моих плечах раньше, чем я успела сказать хоть слово.", "zh": "我带着一整周的工作压力走进来，走出去时它已经不在身上了。我还没开口，理疗师就读出了我肩上的紧绷。", "hi": "मैं पूरे हफ़्ते की डेडलाइनें लेकर अंदर आई और उनके बिना बाहर निकली। मेरे कुछ कहने से पहले ही थेरेपिस्ट ने मेरे कंधों का तनाव पढ़ लिया।"}'::jsonb),
  (1, '-doldurulacak-', '-doldurulacak-', '{"th": "เป็นชั่วโมงที่เงียบที่สุดในรอบหลายเดือน ไม่มีอะไรเร่งรีบ ไม่มีการขายเพิ่ม มีเพียงฝีมือที่ดีจริง และห้องที่ทำให้เราปิดสวิตช์ตัวเองได้", "en": "The quietest hour I have had in months. Nothing rushed, nothing upsold — just genuinely skilled hands and a room that lets you switch off.", "tr": "Aylardır geçirdiğim en sessiz saatti. Ne acele vardı ne de ek satış çabası — sadece gerçekten usta eller ve insanı kapatan bir oda.", "ru": "Самый тихий час за последние месяцы. Никакой спешки, никаких попыток что-то допродать — просто по-настоящему умелые руки и кабинет, в котором получается выключиться.", "zh": "这是我几个月来最安静的一小时。没有催促，也没有推销，只有真正到位的手法，和一个能让人彻底关机的房间。", "hi": "महीनों में मेरा सबसे शांत घंटा। न कोई जल्दबाज़ी, न कुछ अतिरिक्त बेचने की कोशिश — बस सचमुच कुशल हाथ और एक ऐसा कमरा जो आपको बंद हो जाने देता है।"}'::jsonb),
  (2, '-doldurulacak-', '-doldurulacak-', '{"th": "ฉันนวดแผนไทยมาเยอะมากตลอดหลายปี ที่นี่คือของจริง เทคนิคถูกต้อง น้ำหนักมือพอดี และนักบำบัดที่รับฟังจริง ๆ", "en": "I have had a lot of Thai massage over the years. This is the real thing: proper technique, proper pressure, and a therapist who actually listens.", "tr": "Yıllar içinde çok Tayland masajı yaptırdım. Bu gerçek olanı: doğru teknik, doğru basınç ve gerçekten dinleyen bir terapist.", "ru": "За годы я перепробовал много тайского массажа. Здесь всё настоящее: верная техника, верное давление и мастер, который действительно слушает.", "zh": "这些年我做过很多泰式按摩。这里是货真价实的：手法对、力度对，理疗师也是真的在听你说话。", "hi": "इन वर्षों में मैंने बहुत थाई मसाज करवाई है। यह असली वाली है: सही तकनीक, सही दबाव, और एक थेरेपिस्ट जो वाकई सुनता है।"}'::jsonb);
